    /// near-ties are the point: 0.35, 2.675 and 231.45 sit just below their
    /// midpoints in binary, 0.25 and -2.5 are exact ties that go to even.
    /// </summary>
    [Theory]
    [InlineData("0.05", "0.1")]
    [InlineData("0.15", "0.1")]
    [InlineData("0.25", "0.2")]
    [InlineData("0.35", "0.3")]
    [InlineData("0.45", "0.5")]
    [InlineData("0.55", "0.6")]
    [InlineData("2.675", "2.7")]
    [InlineData("12.35", "12.3")]
    [InlineData("231.45", "231.4")]
    [InlineData("-0.04", "-0.0")]
    [InlineData("-0.05", "-0.1")]
    [InlineData("-0.15", "-0.1")]
    [InlineData("-2.5", "-2.5")]
    [InlineData("1e+16", "1e+16")]
    [InlineData("1000000000000000.0", "1000000000000000.0")]
    [InlineData("1e-05", "0.0")]
    [InlineData("0.0001", "0.0")]
    [InlineData("123456.789", "123456.8")]
    [InlineData("99.95", "100.0")]
    [InlineData("89.95", "90.0")]
    [InlineData("3.25", "3.2")]
    [InlineData("7.75", "7.8")]
    [InlineData("0.0", "0.0")]
    [InlineData("1.05", "1.1")]
    [InlineData("4.35", "4.3")]
    [InlineData("1e+22", "1e+22")]
    [InlineData("5e-324", "0.0")]
    [InlineData("1.7976931348623157e+308", "1.7976931348623157e+308")]
    [InlineData("4503599627370495.5", "4503599627370495.5")]
    [InlineData("450359962737049.56", "450359962737049.6")]
    [InlineData("45035996273704.95", "45035996273705.0")]
    [InlineData("-352.33", "-352.3")]
    [InlineData("-210.4", "-210.4")]
    [InlineData("-855.1", "-855.1")]
    [InlineData("-268.6", "-268.6")]
    [InlineData("819.41", "819.4")]
    [InlineData("-925.0087", "-925.0")]
    [InlineData("-163.66", "-163.7")]
    [InlineData("-818.574", "-818.6")]
    [InlineData("-881.8", "-881.8")]
    [InlineData("894.9", "894.9")]
    [InlineData("154.2059", "154.2")]
    [InlineData("-900.82", "-900.8")]
    [InlineData("-906.83", "-906.8")]
    [InlineData("-420.78", "-420.8")]
    [InlineData("81.372", "81.4")]
    [InlineData("120.51", "120.5")]
    [InlineData("-793.89", "-793.9")]
    [InlineData("-255.2", "-255.2")]
    [InlineData("128.74", "128.7")]
    [InlineData("-7.171", "-7.2")]
    [InlineData("554.4575", "554.5")]
    [InlineData("171.1237", "171.1")]
    [InlineData("-276.84", "-276.8")]
    [InlineData("588.76", "588.8")]
    [InlineData("-836.29", "-836.3")]
    [InlineData("50.393", "50.4")]
    [InlineData("458.891", "458.9")]
    [InlineData("217.9", "217.9")]
    [InlineData("-763.8684", "-763.9")]
    [InlineData("-670.076", "-670.1")]
    [InlineData("-696.0309", "-696.0")]
    [InlineData("-156.6", "-156.6")]
    [InlineData("529.142", "529.1")]
    [InlineData("-319.755", "-319.8")]
    [InlineData("188.7398", "188.7")]
    [InlineData("-862.5", "-862.5")]
    [InlineData("889.3622", "889.4")]
    [InlineData("394.1", "394.1")]
    [InlineData("-878.661", "-878.7")]
    [InlineData("294.2577", "294.3")]
    public void Round_and_repr_match_python(string repr, string rounded)
    {
        var x = double.Parse(repr, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture);
        Assert.Equal(repr, PyJson.FloatRepr(x));
        Assert.Equal(rounded, PyJson.FloatRepr(PyJson.Round(x, 1)));
    }
}
